## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define INF (LLONG_MAX / 4)

#include <limits.h>

static int compara_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;

    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, K;

    if (scanf("%d %d", &N, &K) != 2) {
        return 0;
    }

    int *T = malloc((size_t)N * sizeof(int));
    if (T == NULL) {
        return 0;
    }

    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
    }

    qsort(T, (size_t)N, sizeof(int), compara_int);

    long long *dp_i_menos_2 = malloc((size_t)(K + 1) * sizeof(long long));
    long long *dp_i_menos_1 = malloc((size_t)(K + 1) * sizeof(long long));
    long long *dp_atual = malloc((size_t)(K + 1) * sizeof(long long));

    if (dp_i_menos_2 == NULL || dp_i_menos_1 == NULL || dp_atual == NULL) {
        free(T);
        free(dp_i_menos_2);
        free(dp_i_menos_1);
        free(dp_atual);
        return 0;
    }

    for (int j = 0; j <= K; j++) {
        dp_i_menos_2[j] = INF;
    }
    dp_i_menos_2[0] = 0;

    /* Para i = 1, a linha anterior e a linha i-2 correspondem a dp[0]. */
    for (int j = 0; j <= K; j++) {
        dp_i_menos_1[j] = dp_i_menos_2[j];
    }

    for (int i = 1; i <= N - 1; i++) {
        for (int j = 0; j <= K; j++) {
            dp_atual[j] = dp_i_menos_1[j];
        }

        if (i >= 2) {
            long long diferenca = (long long)T[i - 1] - T[i - 2];
            long long custo = diferenca * diferenca;

            for (int j = 1; j <= K; j++) {
                int limite = N - 3 * (K - j) - 1;

                if (i <= limite && dp_i_menos_2[j - 1] != INF) {
                    long long candidato = dp_i_menos_2[j - 1] + custo;
                    if (candidato < dp_atual[j]) {
                        dp_atual[j] = candidato;
                    }
                }
            }
        }

        long long *temporario = dp_i_menos_2;
        dp_i_menos_2 = dp_i_menos_1;
        dp_i_menos_1 = dp_atual;
        dp_atual = temporario;
    }

    printf("%lld\n", dp_i_menos_1[K]);

    free(T);
    free(dp_i_menos_2);
    free(dp_i_menos_1);
    free(dp_atual);

    return 0;
}
```

